import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class ArgumentNullException extends BaseException {
    public static type: string = 'System.ArgumentNullException';

    constructor(argumentName: string) {
        super(ArgumentNullException.type, `Argument not defined: ${argumentName}`);
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
